package com.duozhi.outbound;

import java.util.*;
import java.time.*;
import java.util.concurrent.*;
import javax.servlet.http.HttpServletRequest;
import javax.annotation.PreDestroy;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import org.springframework.web.servlet.mvc.method.annotation.ResponseBodyEmitter;

@RestController
public class AgentMedia {
    private final Store store;private final Config config;private final Contract contract;private final JsonSupport json;private final ExpiringValues values;private final Transactions tx;
    private final ScheduledExecutorService events=Executors.newScheduledThreadPool(2,r->{Thread t=new Thread(r,"agent-events");t.setDaemon(true);return t;});
    private final Semaphore slots=new Semaphore(100);
    public AgentMedia(Store store,Config config,Contract contract,JsonSupport json,ExpiringValues values,Transactions tx){this.store=store;this.config=config;this.contract=contract;this.json=json;this.values=values;this.tx=tx;}
    @PreDestroy public void close(){events.shutdownNow();}
    private Identity agent(HttpServletRequest request){Identity i=Identity.from(request);if(!"agent".equals(i.requireUser().get("role")))throw new ApiError(403,"agent role required");return i;}
    private String extension(Object id){String ext=config.get("WEBRTC_EXTENSION_TEMPLATE","agent_{agent_id}").replace("{agent_id}",id.toString());if(!ext.matches("[A-Za-z0-9_.-]+"))throw new ApiError(503,"invalid SIP extension template");return ext;}
    private String mediaKey(long tenant,Object id){return "ai-outbound:agent-media:"+tenant+":"+id;}
    public void clear(long tenant,Object id){values.delete(mediaKey(tenant,id));}
    public boolean registered(long tenant,Object id){String raw=values.get(mediaKey(tenant,id));if(raw==null)return false;Map<String,Object> data=json.object(raw);return "registered".equals(data.get("registration_state"))&&"granted".equals(data.get("microphone_permission"));}
    @PostMapping("/api/v1/agent/webrtc/session") public Map<String,Object> session(HttpServletRequest request){Identity i=agent(request);if(!config.flag("WEBRTC_ENABLED",false))return contract.output("WebRtcSessionOut",contract.input("WebRtcSessionOut",JsonSupport.map("enabled",false,"ice_servers",Collections.emptyList()),true));
        String wss=config.get("WEBRTC_WSS_URL",""),domain=config.get("WEBRTC_SIP_DOMAIN","");if(!wss.startsWith("wss://")||domain.trim().isEmpty())throw new ApiError(503,"secure WebRTC endpoint is not configured");
        String ext=extension(i.userId()),key="ai-outbound:sip-extension:"+ext,raw=values.get(key),password="";if(raw!=null){Map<String,Object> old=json.object(raw);if(Objects.toString(old.get("tenant_id"),"").equals(""+i.tenant())&&Objects.toString(old.get("agent_id"),"").equals(i.userId().toString()))password=Objects.toString(old.get("password"),"");}
        if(password.isEmpty()){byte[] bytes=new byte[24];new java.security.SecureRandom().nextBytes(bytes);password=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}
        int ttl=Math.max(60,config.number("WEBRTC_SIP_CREDENTIAL_TTL_SEC",900));String expires=Store.now().plusSeconds(ttl).toString();values.set(key,json.json(JsonSupport.map("tenant_id",i.tenant(),"agent_id",i.userId(),"extension",ext,"password",password,"expires_at",expires)),ttl);
        List<String> stun=new ArrayList<>(),turn=new ArrayList<>();for(String url:config.get("TURN_URLS","").split(",")){url=url.trim();if(url.toLowerCase(Locale.ROOT).startsWith("stun:"))stun.add(url);if(url.toLowerCase(Locale.ROOT).startsWith("turn:")||url.toLowerCase(Locale.ROOT).startsWith("turns:"))turn.add(url);}
        List<Map<String,Object>> ice=new ArrayList<>();if(!stun.isEmpty())ice.add(JsonSupport.map("urls",stun));String secret=config.get("TURN_SHARED_SECRET","");if(!turn.isEmpty()){if(secret.isEmpty()){if(config.production())throw new ApiError(503,"TURN_SHARED_SECRET is required");}else try{String username=(Instant.now().getEpochSecond()+Math.max(60,config.number("TURN_CREDENTIAL_TTL_SEC", 3600)))+":agent-"+i.userId();javax.crypto.Mac mac=javax.crypto.Mac.getInstance("HmacSHA1");mac.init(new javax.crypto.spec.SecretKeySpec(secret.getBytes(java.nio.charset.StandardCharsets.UTF_8),"HmacSHA1"));ice.add(JsonSupport.map("urls",turn,"username",username,"credential",Base64.getEncoder().encodeToString(mac.doFinal(username.getBytes(java.nio.charset.StandardCharsets.UTF_8)))));}catch(java.security.GeneralSecurityException e){throw new IllegalStateException(e);}}
        return JsonSupport.map("enabled",true,"wss_url",wss,"sip_uri","sip:"+ext+"@"+domain,"authorization_username",ext,"authorization_password",password,"extension",ext,"expires_at",expires,"ice_servers",ice);
    }
    @GetMapping("/api/v1/agent/media/status") public Map<String,Object> status(HttpServletRequest request){Identity i=agent(request);String raw=values.get(mediaKey(i.tenant(),i.userId()));if(raw!=null)return json.object(raw);Map<String,Object> result=contract.input("AgentMediaStatusUpdate",JsonSupport.map("registration_state",config.flag("WEBRTC_ENABLED",false)?"disconnected":"disabled","media_state","idle","microphone_permission","unknown"),true);result.putAll(JsonSupport.map("user_id",i.userId(),"tenant_id",i.tenant(),"extension",extension(i.userId()),"registration_state",config.flag("WEBRTC_ENABLED",false)?"disconnected":"disabled","last_seen_at",Store.now()));return result;}
    @PutMapping("/api/v1/agent/media/status") public Map<String,Object> update(@RequestBody Map<String,Object> body,HttpServletRequest request){Map<String,Object> data=contract.input("AgentMediaStatusUpdate",body,true);Identity i=agent(request);if(data.get("active_call_id")!=null){Map<String,Object> call=store.require("callsession",i.tenant(),data.get("active_call_id"));if(!Objects.toString(call.get("human_agent_id"),"").equals(i.userId().toString()))throw new ApiError(403,"active call is not assigned to this agent");}
        data.putAll(JsonSupport.map("tenant_id",i.tenant(),"user_id",i.userId(),"extension",extension(i.userId()),"last_seen_at",Store.now().toString()));values.set(mediaKey(i.tenant(),i.userId()),json.json(data),Math.max(30,config.number("WEBRTC_MEDIA_STATUS_TTL_SEC",90)));
        tx.run(()->{Map<String,Object> row=store.require("user",i.tenant(),i.userId()),changes=JsonSupport.map("last_seen_at",Store.now());if(config.flag("WEBRTC_ENABLED",false)&&!"registered".equals(data.get("registration_state"))&&"ready".equals(row.get("agent_status")))changes.put("agent_status","offline");store.update("user",i.tenant(),i.userId(),changes);return null;});return data;
    }
    @GetMapping("/api/v1/agent/events/stream") public ResponseEntity<ResponseBodyEmitter> stream(HttpServletRequest request){Identity i=agent(request);if(!slots.tryAcquire())throw new ApiError(503,"agent stream capacity reached");ResponseBodyEmitter emitter=new ResponseBodyEmitter(0L);java.util.concurrent.atomic.AtomicBoolean closed=new java.util.concurrent.atomic.AtomicBoolean();final ScheduledFuture<?>[] future=new ScheduledFuture<?>[1];Runnable finish=()->{if(closed.compareAndSet(false,true)){slots.release();if(future[0]!=null)future[0].cancel(false);}};emitter.onCompletion(finish);emitter.onTimeout(finish);emitter.onError(e->finish.run());String[] previous={""};long[] sent={0};
        future[0]=events.scheduleWithFixedDelay(()->{try{if(closed.get())return;if(request.getAttribute("token_expires_at") instanceof Number&&Instant.now().getEpochSecond()>=((Number)request.getAttribute("token_expires_at")).longValue()){finish.run();emitter.complete();return;}Map<String,Object> user=store.require("user",i.tenant(),i.userId());if(!Boolean.TRUE.equals(user.get("enabled"))||!Objects.equals(user.get("token_version"),i.user().get("token_version"))){finish.run();emitter.complete();return;}
            List<Map<String,Object>> handoff=new ArrayList<>(),calls=new ArrayList<>();for(Map<String,Object> h:store.list("handoffrequest","WHERE tenant_id=? AND state IN ('WAITING','ACCEPTING','ACCEPTED') AND (assigned_agent_id IS NULL OR assigned_agent_id=?)",i.tenant(),i.userId()))handoff.add(JsonSupport.map("id",h.get("id"),"call_session_id",h.get("call_session_id"),"state",h.get("state"),"updated_at",h.get("updated_at")));for(Map<String,Object> c:store.list("callsession","WHERE tenant_id=? AND human_agent_id=? AND status NOT IN ('COMPLETED','FAILED','NO_ANSWER','BUSY','VOICEMAIL')",i.tenant(),i.userId()))calls.add(JsonSupport.map("id",c.get("id"),"status",c.get("status"),"updated_at",c.get("updated_at")));Map<String,Object> snapshot=JsonSupport.map("type","agent_snapshot","handoffs",handoff,"calls",calls);String canonical=json.canonical(snapshot,false);long now=System.currentTimeMillis();if(!canonical.equals(previous[0])||now-sent[0]>=15000){snapshot.put("timestamp",Store.now().toString());emitter.send(json.json(snapshot)+"\n",MediaType.APPLICATION_JSON);previous[0]=canonical;sent[0]=now;}
        }catch(Exception e){finish.run();emitter.completeWithError(e);}},0,Math.max(500,(long)(Double.parseDouble(config.get("WEBRTC_EVENT_STREAM_INTERVAL_SEC","1.5"))*1000)),TimeUnit.MILLISECONDS);
        if(closed.get())future[0].cancel(false);
        return ResponseEntity.ok().header("Content-Type","application/x-ndjson").header("Cache-Control","no-store").header("X-Accel-Buffering","no").body(emitter);
    }
    private String xml(Object value){return Objects.toString(value,"").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#x27;");}
    @PostMapping(value="/internal/freeswitch/directory",produces="application/xml") public String directory(@RequestParam(defaultValue="") String user,@RequestParam(defaultValue="") String domain,@RequestParam(defaultValue="") String token){String expected=config.get("FREESWITCH_DIRECTORY_TOKEN","").trim();if(expected.isEmpty()||!Crypto.equal(expected,token))throw new ApiError(401,"invalid directory token");String raw=values.get("ai-outbound:sip-extension:"+user);if(raw==null)return "<document type=\"freeswitch/xml\"><section name=\"result\"><result status=\"not found\" /></section></document>";Map<String,Object> credential=json.object(raw);String ext=xml(credential.get("extension"));return "<document type=\"freeswitch/xml\"><section name=\"directory\"><domain name=\""+xml(domain.isEmpty()?config.get("WEBRTC_SIP_DOMAIN",""):domain)+"\"><groups><group name=\"agents\"><users><user id=\""+ext+"\"><params><param name=\"password\" value=\""+xml(credential.get("password"))+"\"/></params><variables><variable name=\"user_context\" value=\"browser-no-outbound\"/><variable name=\"effective_caller_id_name\" value=\""+ext+"\"/><variable name=\"effective_caller_id_number\" value=\""+ext+"\"/></variables></user></users></group></groups></domain></section></document>";}
}
